// And groups predicates with the AND operator between them.
func And(predicates ...predicate.TranslationContribution) predicate.TranslationContribution {
	return predicate.TranslationContribution(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.TranslationContribution) predicate.TranslationContribution {
	return predicate.TranslationContribution(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.TranslationContribution) predicate.TranslationContribution {
	return predicate.TranslationContribution(sql.NotPredicates(p))
}
